    let planeAt = planeNdcPerUV;
    let maxPenumbraUV = min(24.0 * texelSize, 1.8 / orthoWidth);
    let cs = cos(noiseRot);
    let sn = sin(noiseRot);
    let rot = mat2x2f(cs, -sn, sn, cs);

