    let blockerDist = (blockerDepthSum / blockerCount) * depthRange;
    let penumbraWorld = blockerDist * 0.0093 * softness;
    let filterR = clamp(penumbraWorld / orthoWidth, texelSize, maxPenumbraUV);

    var lit = 0.0;
