    vertexOutputs.vNormal = n;
    vertexOutputs.vInfo = vec4f(s.phi, s.lip, s.u, s.foamT);
    vertexOutputs.vInfo2 = vec4f(d0, s.thick, s.kind, distance(s.pos, uniforms.cameraPos));
    vertexOutputs.vParam = vec2f(x, d0);
    vertexOutputs.vDeep = 0.0;
    vertexOutputs.position = uniforms.viewProjection * vec4f(s.pos, 1.0);
