    let phi = input.vInfo.x;
    let lip = input.vInfo.y;
    let u = input.vInfo.z;
    let foamT = input.vInfo.w;
    let thick = max(input.vInfo2.y, 0.03);

    var N = normalize(input.vNormal);
    let backFace = dot(N, V) < 0.0;
    if (backFace) { N = -N; }
    let geoN = N;

    // ---- detail normals ----------------------------------------------------
    // Tangent frame in the surface parametrization: T along x, B across.
    var T = vec3f(1.0, 0.0, 0.0) - N * N.x;
    T = normalize(T);
    let B = cross(N, T);
    let ddxW = dpdx(world);
    let ddyW = dpdy(world);
    let footprint = max(length(vec2f(length(ddxW), length(ddyW))), 1e-4);
    let t = uniforms.time;
    let det = uniforms.detailStrength;
    let fadeCoarse = 1.0 - smoothstep(0.25, 1.4, footprint);
    let fadeFine = 1.0 - smoothstep(0.02, 0.16, footprint);
