    let n1 = detailNormal(p, 0.5, vec2f(t * 0.06, -t * 0.045));
    let n1b = detailNormal(p + vec2f(3.7, 1.3), 0.73, vec2f(-t * 0.05, t * 0.03));
    let n2 = detailNormal(p, 0.08, vec2f(t * 0.18, t * 0.11));
    // Fade detail into the lip: a thrown sheet is smooth and stretched.
    let sheetFade = (1.0 - 0.9 * lip) * select(1.0, 0.35, backFace);
    let ampC = 0.55 * det * fadeCoarse * sheetFade;
    let ampF = 0.35 * det * fadeFine * sheetFade;
    let wg = wakeGradient(pWave.x, pWave.y) * (1.0 - smoothstep(0.1, 0.6, footprint));
