    // ---- foam ----------------------------------------------------------------
    let st = foamState(pWave.x, pWave.y);
    let feather = smoothstep(0.15, 0.85, phi) * smoothstep(0.62, 1.0, lip);
    // The bore's own whitewater sits on the mound (u in -0.5..0.75) and trails
    // behind it; the flats ahead stay clean until the state buffer (M5) paints
    // them. \`foamT\` alone is the break phase, which is the same at every u.
    let moundMask = (1.0 - smoothstep(0.75, 1.1, u)) * smoothstep(-1.8, -0.45, u);
    let bore = foamT * moundMask;
    var foamDensity = clamp(max(st.x, max(bore * 0.9, feather * 0.8)), 0.0, 1.0);
    // Worley breakup so patches dissolve into feathered trails; age drives it.
    let age = st.y;
    let w1 = worley2(p * 2.6 + vec2f(t * 0.05, 0.0));
    let w2 = worley2(p * 9.0 - vec2f(0.0, t * 0.08));
    let breakup = clamp(0.35 + 0.65 * (1.0 - w1 * 0.8) * (1.0 - w2 * 0.45), 0.0, 1.0);
    let dissolve = smoothstep(0.0, 1.0, foamDensity * (1.0 + 0.5 * breakup) - (0.12 + 0.5 * clamp(age / 8.0, 0.0, 1.0)) * (1.0 - breakup));
    let foam = clamp(dissolve, 0.0, 1.0);
    let aeration = clamp(max(st.z, bore * 0.8 + feather * 0.5), 0.0, 1.0);

    // ---- refraction and absorption -------------------------------------------
    // \`fragmentInputs.position\` is the engine-adjusted fragment coordinate
