    let bodyLight = (sun * max(0.35, L.y) * mix(0.55, 1.0, shadow) + skyIrr) * INV_PI;
    // Deep water is blue-green, darker and bluer than the scatter tint of the
    // thin lip; the two are different things.
    let bodyColor = vec3f(0.012, 0.075, 0.13) * bodyLight;
    var color = op.rgb * trans + bodyColor * (1.0 - trans);

    // ---- subsurface scattering ---------------------------------------------
    // Thin where the lip is, thick at the trough. Backlit from the chase camera
    // the lip and the curtain glow green.
    // Only a thin sheet transmits: the lip, the curtain, the crest's top.
    let thinW = 1.0 / (1.0 + thick * thick * 6.0);
    let back = backScatter(N, L, V, 0.35, mix(2.2, 6.0, 1.0 - thinW), 1.0);
    let wrap = wrapDiffuse(NdotL, 0.55);
    var sss = uniforms.scatterColor * sun * INV_PI * uniforms.sssStrength
