    let c3 = worley2(cp * 0.6 + vec2f(-t * 0.04, t * 0.06) + 11.0);
    var caust = pow(clamp(1.0 - c1, 0.0, 1.0), 3.0) * 0.6 + pow(clamp(1.0 - c2, 0.0, 1.0), 4.0) * 0.5 + pow(clamp(1.0 - c3, 0.0, 1.0), 2.0) * 0.3;
