    if (abs(uniforms.contrast - 1.0) > 0.001) {
        c = 0.18 * pow(max(c / 0.18, vec3f(1e-5)), vec3f(uniforms.contrast));
    }

    var mapped: vec3f;
    if (uniforms.mode < 0.5) {
        mapped = acesFitted(c);
    } else if (uniforms.mode < 1.5) {
        var v = agx(c);
        v = agxLook(v, 1.12);
        mapped = pow(max(AGX_OUT * v, vec3f(0.0)), vec3f(2.2));
    } else {
        mapped = clamp(c, vec3f(0.0), vec3f(1.0));
    }

    let dv = length((uv - vec2f(0.5)) * vec2f(uniforms.aspect, 1.0)) / length(vec2f(uniforms.aspect, 1.0)) * 2.0;
    let vig = mix(1.0, smoothstep(1.15, 0.35, dv), uniforms.vignette + uw * 0.5);
