    if (i >= params.count) { return; }
    let smp = samples[i];
    var wu: WaveUniforms;
    wu.origin = params.origin;
    wu.xb = params.xb;
    wu.t = smp.z;
    wu.bend = params.bend;
    wu.sweep = params.sweep;
    wu.zoff = params.waveSpeed * smp.z;
    wu.waveSpeed = params.waveSpeed;
    wu.setA = params.setA; wu.setB = params.setB; wu.setAmp = params.setAmp; wu.setOn = params.setOn;
